  letter-spacing: 0.04em;
  text-transform: uppercase;
  padding: 5px 14px;
  border-radius: 100px;
  margin-bottom: 20px;
}

.page-header h1 {
  font-size: clamp(2rem, 5vw, 2.75rem);
  font-weight: 800;
  letter-spacing: -0.03em;
  color: var(--text-primary);
  line-height: 1.15;
  margin-bottom: 16px;
}

.page-header h1 span {
  color: var(--accent);
}

.page-header p {
  font-size: 1.05rem;
  color: var(--text-secondary);
  max-width: 480px;
  margin: 0 auto;
}

/* ── FAQ container ── */
.faq-container {
  max-width: 720px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

/* ── Section headings ── */
.faq-section-label {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text-muted);
  padding: 8px 4px 4px;
  margin-top: 12px;
}

/* ── Individual FAQ item ── */
.example {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow-sm);
  overflow: hidden;
  transition: box-shadow var(--transition), border-color var(--transition);
}

.example:hover {
  box-shadow: var(--shadow-md);
  border-color: #d0d5e0;
}

.example.open {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(108, 99, 255, 0.08), var(--shadow-md);
}

/* ── Question / trigger button ── */
.faq-trigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  width: 100%;
  padding: 20px 24px;
  background: none;
  border: none;
  cursor: pointer;
  text-align: left;
  color: var(--text-primary);
  font-size: 1rem;
  font-weight: 600;
  transition: background var(--transition);
}

.faq-trigger:hover {
  background: #fafbfc;
}

.example.open .faq-trigger {
  background: var(--accent-light);
  color: var(--accent);
}

.faq-trigger .question-text {
  flex: 1;
}

.faq-icon {
  flex-shrink: 0;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--bg);
  border: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: transform var(--transition), background var(--transition), border-color var(--transition);
}

.example.open .faq-icon {
  background: var(--accent);
  border-color: var(--accent);
  transform: rotate(45deg);
}

.faq-icon svg {
  display: block;
  color: var(--text-muted);
  transition: color var(--transition);
}

.example.open .faq-icon svg {
  color: #fff;
}

/* ── Controlled content wrapper ── */
.details {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows var(--transition);
}

.example.open .details {
  grid-template-rows: 1fr;
}

.details-inner {
  overflow: hidden;
}

.details-body {
  padding: 0 24px 22px;
  font-size: 0.96rem;
  color: var(--text-secondary);
  line-height: 1.75;
  border-top: 1px solid var(--border);
  padding-top: 18px;
}

.details-body p + p {
  margin-top: 12px;
}

.details-body strong {
  color: var(--text-primary);
}

/* ── Footer ── */
.page-footer {
  text-align: center;
  margin-top: 64px;
  color: var(--text-muted);
  font-size: 0.875rem;
}

.page-footer a {
  color: var(--accent);
  text-decoration: none;
}
